#!/bin/sh
# Regenerate generated/*.S from the CRYPTOGAMS perlasm in arm/ (needs only
# perl). The output is checked in so that building needs no perl.
# Flavour linux32: GNU assembler syntax, which VitaSDK's binutils accept.
set -eu
cd "$(dirname "$0")"
for f in chacha-armv4 poly1305-armv4; do
	{
		printf '/* Generated by third_party/cryptogams/generate.sh from arm/%s.pl\n' "$f"
		printf ' * (CRYPTOGAMS by @dot-asm, see ../LICENSE). Do not edit. */\n'
		perl "arm/$f.pl" linux32 /dev/stdout
	} > "generated/$f.S"
done
